create extension if not exists pgcrypto;
create table if not exists leads(id uuid primary key default gen_random_uuid(),name text,phone text not null,business_name text,business_type text,city text,requirement text,gst_status text,udyam_status text,funding_amount text,temperature text check (temperature in ('HOT','WARM','COLD')) default 'COLD',status text default 'NEW',service text,potential_value numeric default 0,source text default 'whatsapp',created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists conversations(id uuid primary key default gen_random_uuid(),lead_id uuid references leads(id) on delete cascade,direction text check(direction in ('inbound','outbound')),message text,provider_message_id text,created_at timestamptz default now());
create table if not exists payments(id uuid primary key default gen_random_uuid(),lead_id uuid references leads(id) on delete set null,amount numeric not null,currency text default 'INR',status text default 'PENDING',provider text,provider_payment_id text,created_at timestamptz default now());
create table if not exists followups(id uuid primary key default gen_random_uuid(),lead_id uuid references leads(id) on delete cascade,scheduled_for timestamptz not null,channel text default 'whatsapp',status text default 'PENDING',created_at timestamptz default now());
create index if not exists leads_phone_idx on leads(phone);create index if not exists leads_status_idx on leads(status);create index if not exists followups_due_idx on followups(scheduled_for,status);
